import{j as e,H as i}from"./index-CoySgEe1.js";const o=[{h:"Overview",p:`Nuvae ("we," "us") provides AI-based revenue-protection software to healthcare organizations. This policy explains what information we collect, how we use it, and how it's protected — including protected health information (PHI) processed on behalf of our hospital and health system customers.`},{h:"Information we collect",p:"Account and contact information you provide directly (name, work email, hospital affiliation); usage data from your interaction with our software; and, where applicable under a signed Business Associate Agreement (BAA), protected health information processed solely to deliver the contracted service."},{h:"How we use information",p:"To operate and improve the Nuvae platform; to communicate with you about your account or service; and, for PHI processed under a BAA, exclusively for the purposes permitted by that agreement and the Health Insurance Portability and Accountability Act (HIPAA)."},{h:"PHI and HIPAA",p:"Where Nuvae processes protected health information on behalf of a covered entity, that processing is governed by a signed Business Associate Agreement (BAA), not this general policy. Contact us to request a BAA before submitting any PHI."},{h:"Data security",p:"Data is encrypted in transit and at rest. Access is role-based and logged. We do not write PHI to application logs. Nuvae is HIPAA compliant and SOC 2 Type II certified — see our Trust Center for the full security and compliance posture."},{h:"Data retention & deletion",p:"We retain data for as long as needed to provide the service or as required by law and applicable BAAs, and delete or return data on contract termination consistent with BAA terms. [TODO: confirm specific retention periods with legal/ops before publishing.]"},{h:"Third parties",p:"We do not sell personal information or PHI. Subprocessors used to deliver the service are bound by contractual confidentiality and, where applicable, BAA terms. [TODO: list actual subprocessors before publishing.]"},{h:"Your rights",p:"You may request access to, correction of, or deletion of your personal information, subject to legal and contractual obligations (including HIPAA retention requirements for PHI). Contact manu@nuvae.ai."},{h:"Changes to this policy",p:"We'll post material changes here with an updated effective date."},{h:"Contact",p:"Questions about this policy: manu@nuvae.ai."}];function n(){return e.jsxs(e.Fragment,{children:[e.jsxs(i,{children:[e.jsx("title",{children:"Privacy Policy — Nuvae"}),e.jsx("meta",{name:"description",content:"How Nuvae collects, uses, and protects information, including PHI under HIPAA."}),e.jsx("link",{rel:"canonical",href:"https://nuvae.ai/privacy"})]}),e.jsx("section",{className:"scene light legal",id:"privacy",children:e.jsxs("div",{className:"wrap legal-wrap",children:[e.jsx("p",{className:"kicker",children:"Privacy Policy"}),e.jsx("h1",{className:"h-big",children:"Privacy Policy"}),e.jsx("div",{className:"legal-disclaimer",children:"This page is a working draft prepared for a healthcare software vendor and has not been reviewed by legal counsel. Do not publish without review by a qualified attorney familiar with HIPAA, state privacy law, and your specific data-processing arrangements."}),o.map((a,t)=>e.jsxs("div",{className:"legal-section",children:[e.jsxs("h2",{className:"h-mid",children:[t+1,". ",a.h]}),e.jsx("p",{className:"sub legal-p",children:a.p})]},a.h))]})})]})}export{n as default};
